CREATE TABLE images (id INTEGER PRIMARY KEY AUTOINCREMENT, group_id INTEGER, film_id INTEGER,  width INTEGER, height INTEGER, filename VARCHAR,  maker_id INTEGER, model_id INTEGER, lens_id INTEGER, camera_id INTEGER,  exposure REAL, aperture REAL, iso REAL, focal_length REAL,  focus_distance REAL, datetime_taken INTEGER, flags INTEGER,  output_width INTEGER, output_height INTEGER, crop REAL,  raw_parameters INTEGER, raw_black INTEGER, raw_maximum INTEGER,  orientation INTEGER, longitude REAL,  latitude REAL, altitude REAL, color_matrix BLOB, colorspace INTEGER,  version INTEGER, max_version INTEGER, write_timestamp INTEGER,  history_end INTEGER, position INTEGER, aspect_ratio REAL, exposure_bias REAL,  import_timestamp INTEGER DEFAULT -1, change_timestamp INTEGER DEFAULT -1,   export_timestamp INTEGER DEFAULT -1, print_timestamp INTEGER DEFAULT -1,   thumb_timestamp INTEGER DEFAULT -1, thumb_maxmip INTEGER DEFAULT 0,   whitebalance_id INTEGER, flash_id INTEGER,   exposure_program_id INTEGER, metering_mode_id INTEGER, flash_tagvalue INTEGER DEFAULT -1, FOREIGN KEY(maker_id) REFERENCES makers(id) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY(model_id) REFERENCES models(id) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY(lens_id) REFERENCES lens(id) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY(camera_id) REFERENCES cameras(id) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY(film_id) REFERENCES film_rolls(id) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY(group_id) REFERENCES images(id) ON DELETE RESTRICT ON UPDATE CASCADE, FOREIGN KEY(whitebalance_id) REFERENCES whitebalance(id) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY(flash_id) REFERENCES flash(id) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY(exposure_program_id) REFERENCES exposure_program(id) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY(metering_mode_id) REFERENCES metering_mode(id) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX images_group_id_index ON images (group_id, id);
CREATE INDEX images_film_id_index ON images (film_id, filename);
CREATE INDEX images_filename_index ON images (filename, version);
CREATE INDEX image_position_index ON images (position);
CREATE INDEX images_datetime_taken_nc ON images (datetime_taken);
CREATE INDEX images_latlong_index ON images (latitude DESC, longitude DESC);
CREATE TRIGGER remove_makers AFTER DELETE ON images BEGIN  DELETE FROM makers    WHERE id = OLD.maker_id      AND NOT EXISTS (SELECT 1 FROM images WHERE maker_id = OLD.maker_id); END;
CREATE TRIGGER remove_models AFTER DELETE ON images BEGIN  DELETE FROM models    WHERE id = OLD.model_id      AND NOT EXISTS (SELECT 1 FROM images WHERE model_id = OLD.model_id); END;
CREATE TRIGGER remove_lens AFTER DELETE ON images BEGIN  DELETE FROM lens    WHERE id = OLD.lens_id      AND NOT EXISTS (SELECT 1 FROM images WHERE lens_id = OLD.lens_id); END;
CREATE TRIGGER remove_cameras AFTER DELETE ON images BEGIN  DELETE FROM cameras    WHERE id = OLD.camera_id      AND NOT EXISTS (SELECT 1 FROM images WHERE camera_id = OLD.camera_id); END;
CREATE TABLE film_rolls (id INTEGER PRIMARY KEY, access_timestamp INTEGER, folder VARCHAR(1024) NOT NULL);
CREATE INDEX film_rolls_folder_index ON film_rolls (folder);
CREATE TABLE tagged_images (imgid INTEGER, tagid INTEGER, position INTEGER, PRIMARY KEY (imgid, tagid),FOREIGN KEY(imgid) REFERENCES images(id) ON UPDATE CASCADE ON DELETE CASCADE);
CREATE INDEX tagged_images_tagid_index ON tagged_images (tagid);
CREATE INDEX tagged_images_position_index ON tagged_images (position);
CREATE TABLE history (imgid INTEGER, num INTEGER, module INTEGER, operation VARCHAR(256), op_params BLOB, enabled INTEGER, blendop_params BLOB, blendop_version INTEGER, multi_priority INTEGER, multi_name VARCHAR(256), multi_name_hand_edited INTEGER, FOREIGN KEY(imgid) REFERENCES images(id) ON UPDATE CASCADE ON DELETE CASCADE);
CREATE INDEX history_imgid_op_index ON history (imgid, operation);
CREATE INDEX history_imgid_num_index ON history (imgid, num DESC);
CREATE TABLE history_hash (imgid INTEGER PRIMARY KEY,  basic_hash BLOB, auto_hash BLOB, current_hash BLOB,  mipmap_hash BLOB,  FOREIGN KEY(imgid) REFERENCES images(id) ON UPDATE CASCADE ON DELETE CASCADE);
